<div class="tabs"><?php foreach (['submitted' => 'To verify', 'awaiting' => 'Awaiting payment', 'verified' => 'Verified', 'rejected' => 'Rejected', 'all' => 'All'] as $k => $v): ?><a class="<?= $st === $k ? 'on' : '' ?>" href="<?= e(url('/admin/payments', ['status' => $k])) ?>"><?= $v ?><?= $k !== 'all' && !empty($counts[$k]) ? ' (' . (int) $counts[$k] . ')' : '' ?></a><?php endforeach; ?></div>
<div class="callout info small" style="margin-bottom:16px">Payments are verified manually. Check the M-Pesa/bank statement for the transaction code, then verify. Verifying immediately activates the course or webinar seat and emails the customer.</div>
<div class="table-wrap"><table class="t"><thead><tr><th>Reference</th><th>Customer</th><th>Item</th><th class="num">Amount</th><th>Transaction code</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($items as $p): ?><tr><td><strong><?= e($p['ref']) ?></strong><div class="muted xs"><?= e(ago($p['submitted_at'] ?: $p['created_at'])) ?></div></td><td><?= e($p['name']) ?><div class="muted xs"><?= e($p['email']) ?></div></td><td><?= e($p['item_title']) ?><div class="muted xs"><?= e($p['item_type']) ?></div></td><td class="num"><?= e(money($p['amount'], $p['currency'])) ?></td>
<td><strong><?= e($p['method_ref']) ?></strong><?php if ($p['proof_path']): ?><br><a class="xs" target="_blank" href="/file/proof/<?= (int) $p['id'] ?>">View proof</a><?php endif; ?></td><td><?= badge($p['status'], ['verified' => 'green', 'submitted' => 'amber', 'rejected' => 'red'][$p['status']] ?? '') ?></td>
<td><?php if (in_array($p['status'], ['submitted', 'awaiting', 'rejected'], true)): ?><div class="tbl-actions"><form method="post" action="/admin/payments/<?= (int) $p['id'] ?>"><?= csrf_field() ?><input type="hidden" name="action" value="verify"><button class="rowbtn" data-confirm="Confirm that you have seen this payment in the statement?">Verify</button></form>
<form method="post" action="/admin/payments/<?= (int) $p['id'] ?>" onsubmit="var r=prompt('Reason shown to the customer:','The transaction code did not match our records.');if(r===null)return false;this.reason.value=r"><?= csrf_field() ?><input type="hidden" name="action" value="reject"><input type="hidden" name="reason"><button class="rowbtn danger">Reject</button></form></div><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="7" class="muted center" style="padding:30px">Nothing here.</td></tr><?php endif; ?></tbody></table></div>
